<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller;use App\Models\User;use App\Services\{AccountChallenges,Administration};use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
class RecoveryController extends Controller{
 public function start(Request $r,AccountChallenges $service){$d=$r->validate(['identity'=>'required|string|max:254','channel'=>'required|in:email,sms','purpose'=>'required|in:verify,reset']);$identity=strtolower(trim($d['identity']));$u=User::where($d['channel']==='email'?'email':'phone',$identity)->first();$id=(string)Str::uuid();if($u&&Administration::active($u)&&($d['purpose']==='reset'||$u->member_type==='applicant')&&($d['channel']==='email'||($u->member_type==='applicant'&&($d['purpose']==='verify'||$u->phone_verified_at))))$id=$service->issue($u,$d['purpose'],$d['channel']);return ['challenge_id'=>$id,'message'=>'If this account can use that channel, a code will be sent. It expires in 10 minutes.'];}
 public function complete(Request $r,AccountChallenges $service){$d=$r->validate(['challenge_id'=>'required|uuid','purpose'=>'required|in:verify,reset','code'=>'required|digits:6','password'=>'required_if:purpose,reset|nullable|string|min:8|max:12|confirmed']);$ok=$service->redeem($d['challenge_id'],$d['purpose'],$d['code'],function($u,$challenge)use($d,$r){if($d['purpose']==='reset'){$u->password=$d['password'];$u->remember_token=Str::random(60);DB::table('sessions')->where('user_id',$u->id)->delete();}else{if($challenge->channel==='email')$u->email_verified_at=now();else $u->phone_verified_at=now();}$u->save();Administration::audit($u,'account.'.$d['purpose'],'user',$u->id);});abort_unless($ok,422,'Invalid, expired or already used code.');if($d['purpose']==='reset'){\Illuminate\Support\Facades\Auth::logout();$r->session()->invalidate();$r->session()->regenerateToken();}return ['message'=>$d['purpose']==='reset'?'Password reset. Sign in with your new password.':'Account verified.'];}
}
